//! Records what the generated `System` of `relay` does on operation sequences,
//! for comparison with the Lean scheduler model by the derived `Conformance.lean`.
//!
//! This is bounded testing, not proof.
//!
//! Usage: `<program> <exhaustive length> <random sequences> <random length>`.
//! Output: one line per sequence, tab-separated: the operations (indices
//! joined by `.`), then one observation per operation: the result, every
//! machine's state and mailbox, and every outbox, as `Debug` prints them.
//!
//! Operations:
//!
//!   0: send to `poke`: (Relay.Ports.Poke.poke 0 : Relay.Ports.Poke)
//!   1: send to `poke`: (Relay.Ports.Poke.poke 1 : Relay.Ports.Poke)
//!   2: send to `poke`: (Relay.Ports.Poke.poke 32768 : Relay.Ports.Poke)
//!   3: send to `poke`: (Relay.Ports.Poke.poke 65535 : Relay.Ports.Poke)
//!   4: step_once
//!   5: take from `report`
//!   6: take from `tap`

use relay_scaffold::plant::{Progress, System};

const OPS: usize = 7;

/// The index of `step_once`. A pseudo-random sequence takes it every second
/// operation on average, so that messages are delivered and not only offered.
const STEP: usize = 4;

fn list<T: std::fmt::Debug>(len: usize, get: impl Fn(usize) -> Option<T>) -> String {
    let items: Vec<String> = (0..len)
        .map(|i| format!("{:?}", get(i).expect("within length")))
        .collect();
    format!("[{}]", items.join(";"))
}

fn observe(system: &System) -> String {
    let mut parts: Vec<String> = Vec::new();
    parts.push(format!("{:?}", system.sink_state()));
    parts.push(list(system.sink_inbox().len(), |i| system.sink_inbox().get(i)));
    parts.push(format!("{:?}", system.source_state()));
    parts.push(list(system.source_inbox().len(), |i| system.source_inbox().get(i)));
    parts.push(list(system.report_outbox().len(), |i| system.report_outbox().get(i)));
    parts.push(list(system.tap_outbox().len(), |i| system.tap_outbox().get(i)));
    parts.join("|")
}

fn apply(system: &mut System, op: usize) -> String {
    let result = match op {
        0 => match system.send_poke(relay_scaffold::types::relay::ports::Poke::Poke(0)) {
            Ok(()) => "ok".to_string(),
            Err(_) => "rej".to_string(),
        },
        1 => match system.send_poke(relay_scaffold::types::relay::ports::Poke::Poke(1)) {
            Ok(()) => "ok".to_string(),
            Err(_) => "rej".to_string(),
        },
        2 => match system.send_poke(relay_scaffold::types::relay::ports::Poke::Poke(32768)) {
            Ok(()) => "ok".to_string(),
            Err(_) => "rej".to_string(),
        },
        3 => match system.send_poke(relay_scaffold::types::relay::ports::Poke::Poke(65535)) {
            Ok(()) => "ok".to_string(),
            Err(_) => "rej".to_string(),
        },
        4 => match system.step_once() {
            Progress::Delivered => "D".to_string(),
            Progress::Settled => "S".to_string(),
            Progress::Blocked => "B".to_string(),
        },
        5 => format!("T:{:?}", system.take_report()),
        6 => format!("T:{:?}", system.take_tap()),
        _ => "?".to_string(),
    };
    format!("{result}|{}", observe(system))
}

fn record(ops: &[usize]) {
    let mut system = System::new();
    let names: Vec<String> = ops.iter().map(|op| op.to_string()).collect();
    let observed: Vec<String> = ops.iter().map(|&op| apply(&mut system, op)).collect();
    println!("{}\t{}", names.join("."), observed.join("\t"));
}

fn main() {
    let args: Vec<usize> = std::env::args()
        .skip(1)
        .map(|a| a.parse().expect("a number"))
        .collect();
    let [exhaustive, random_count, random_length] = args[..] else {
        panic!("usage: <exhaustive length> <random sequences> <random length>");
    };
    // Every sequence of exactly `exhaustive` operations.
    for n in 0..OPS.pow(exhaustive as u32) {
        let mut code = n;
        let ops: Vec<usize> = (0..exhaustive)
            .map(|_| {
                let op = code % OPS;
                code /= OPS;
                op
            })
            .collect();
        record(&ops);
    }
    // Longer sequences from a fixed linear congruential generator.
    let mut state: u64 = 0x9e37_79b9_7f4a_7c15;
    for _ in 0..random_count {
        let ops: Vec<usize> = (0..random_length)
            .map(|_| {
                state = state
                    .wrapping_mul(6_364_136_223_846_793_005)
                    .wrapping_add(1_442_695_040_888_963_407);
                let draw = (state >> 33) as usize;
                if draw.is_multiple_of(2) { STEP } else { (draw / 2) % OPS }
            })
            .collect();
        record(&ops);
    }
}
